content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-color: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 500px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-color);
  margin-bottom: 4px;
}

.header p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.calculator-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  margin-bottom: 24px;
}

.form-group {
  margin-bottom: 16px;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--text-color);
}

.input-field {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-field:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.btn {
  display: inline-block;
  width: 100%;
  padding: 12px;
  font-size: 1rem;
  font-weight: 600;
  text-align: center;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.result-box {
  background-color: #f1f5f9;
  border-radius: 8px;
  padding: 16px;
  text-align: center;
  margin-top: 20px;
}

.result-box h3 {
  font-size: 1.1rem;
  margin-bottom: 8px;
}

.result-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 4px;
}

.history-section {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
}

.history-section h2 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 16px;
}

.history-list {
  list-style: none;
  max-height: 300px;
  overflow-y: auto;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-color);
}

.history-item:last-child {
  border-bottom: none;
}

.history-info {
  font-size: 0.9rem;
}

.history-date {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.badge-normal {
  background-color: #dcfce7;
  color: #166534;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 600;
}

.badge-over {
  background-color: #fee2e2;
  color: #991b1b;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 600;
}

.badge-under {
  background-color: #fef9c3;
  color: #854d0e;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 600;
}

export interface BmiRecord {
  id: string;
  height: number;
  weight: number;
  bmi: number;
  judgment: string;
  date: string;
}

import { useState, useEffect, type FormEvent } from 'react';
import { BmiRecord } from './types';
import './index.css';

export default function App() {
  const [height, setHeight] = useState<string>('');
  const [weight, setWeight] = useState<string>('');
  const [currentBmi, setCurrentBmi] = useState<number | null>(null);
  const [currentJudgment, setCurrentJudgment] = useState<string>('');
  const [history, setHistory] = useState<BmiRecord[]>(() => {
    const saved = localStorage.getItem('bmi_history');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('bmi_history', JSON.stringify(history));
  }, [history]);

  const getBadgeClass = (judgment: string) => {
    if (judgment === 'やせ') return 'badge-under';
    if (judgment === '普通体重') return 'badge-normal';
    return 'badge-over';
  };

  const calculateBmi = (e: FormEvent) => {
    e.preventDefault();
    const h = parseFloat(height);
    const w = parseFloat(weight);

    if (!h || !w || h <= 0 || w <= 0) return;

    const heightInMeters = h / 100;
    const bmiValue = w / (heightInMeters * heightInMeters);
    const roundedBmi = Math.round(bmiValue * 10) / 10;

    let judgment = '';
    if (roundedBmi < 18.5) {
      judgment = 'やせ';
    } else if (roundedBmi < 25) {
      judgment = '普通体重';
    } else {
      judgment = '肥満';
    }

    setCurrentBmi(roundedBmi);
    setCurrentJudgment(judgment);

    const newRecord: BmiRecord = {
      id: Date.now().toString(),
      height: h,
      weight: w,
      bmi: roundedBmi,
      judgment,
      date: new Date().toLocaleDateString('ja-JP', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      }),
    };

    setHistory([newRecord, ...history]);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>BMI計算ツール</h1>
        <p>身長と体重を入力してBMIと判定をチェック</p>
      </header>

      <div className="calculator-card">
        <form onSubmit={calculateBmi}>
          <div className="form-group">
            <label htmlFor="height">身長 (cm)</label>
            <input
              id="height"
              type="number"
              step="0.1"
              className="input-field"
              placeholder="例: 170"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="weight">体重 (kg)</label>
            <input
              id="weight"
              type="number"
              step="0.1"
              className="input-field"
              placeholder="例: 65"
              value={weight}
              onChange={(e) => setWeight(e.target.value)}
              required
            />
          </div>

          <button type="submit" className="btn btn-primary">
            計算する
          </button>
        </form>

        {currentBmi !== null && (
          <div className="result-box">
            <h3>計算結果</h3>
            <div className="result-value">{currentBmi}</div>
            <div>
              判定:{' '}
              <span className={getBadgeClass(currentJudgment)}>
                {currentJudgment}
              </span>
            </div>
          </div>
        )}
      </div>

      <div className="history-section">
        <h2>測定履歴</h2>
        {history.length === 0 ? (
          <p
            style={{
              color: 'var(--text-muted)',
              fontSize: '0.9rem',
              textAlign: 'center',
            }}
          >
            履歴はまだありません
          </p>
        ) : (
          <ul className="history-list">
            {history.map((record) => (
              <li key={record.id} className="history-item">
                <div className="history-info">
                  <div>
                    身長: {record.height}cm / 体重: {record.weight}kg
                  </div>
                  <div className="history-date">{record.date}</div>
                </div>
                <div
                  style={{ display: 'flex', alignItems: 'center', gap: '8px' }}
                >
                  <span style={{ fontWeight: 600 }}>BMI: {record.bmi}</span>
                  <span className={getBadgeClass(record.judgment)}>
                    {record.judgment}
                  </span>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
